const e2e = `// Feature-acceptance E2E for the --since filter: drives the real CLI process.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

const CLI = new URL("../scripts/log-summary.mjs", import.meta.url).pathname;
const FIXTURE = new URL("../fixtures/events.jsonl", import.meta.url).pathname;

function runCli(args) {
  const { status, stdout, stderr } = spawnSync(process.execPath, [CLI, ...args], { encoding: "utf8" });
  return { code: status, stdout, stderr };
}

test("filters the fixture to the window opened at --since", () => {
  const { code, stdout } = runCli(["--since", "2026-01-04T09:05:00Z", FIXTURE]);
  assert.equal(code, 0);
  assert.deepEqual(JSON.parse(stdout), {
    levels: { warn: 1, error: 1, info: 1 },
    first: "2026-01-04T09:05:00Z",
    last: "2026-01-04T09:07:00Z",
  });
});

test("rejects an unparseable --since value without printing a summary", () => {
  const { code, stdout, stderr } = runCli(["--since=not-a-date", FIXTURE]);
  assert.equal(code, 2);
  assert.equal(stdout, "");
  assert.match(stderr, /not-a-date/);
});

test("prints the unchanged summary when --since is absent", () => {
  const { code, stdout } = runCli([FIXTURE]);
  assert.equal(code, 0);
  assert.deepEqual(JSON.parse(stdout), {
    levels: { info: 2, warn: 1, error: 1 },
    first: "2026-01-04T09:00:00Z",
    last: "2026-01-04T09:07:00Z",
  });
});

test("drops untimed and malformed-time events from a filtered window", () => {
  const dir = mkdtempSync(join(tmpdir(), "log-summary-e2e-"));
  const log = join(dir, "mixed.jsonl");
  writeFileSync(log, [
    '{"time":"2026-01-04T09:00:00Z","level":"info"}',
    '{"time":"2026-01-04T09:06:00Z","level":"warn"}',
    '{"level":"error"}',
    '{"time":"garbage","level":"debug"}',
  ].join("\\n") + "\\n");

  const { code, stdout } = runCli(["--since", "2026-01-04T09:05:00Z", log]);
  assert.equal(code, 0);
  assert.deepEqual(JSON.parse(stdout), {
    levels: { warn: 1 },
    first: "2026-01-04T09:06:00Z",
    last: "2026-01-04T09:06:00Z",
  });
});
`;
await tools.write({ path: repo + "/tests/log-summary.feature.test.mjs", content: e2e });

