```js
export function summarize(text, { since } = {}) {
  if (since !== undefined && (typeof since !== "number" || Number.isNaN(since))) {
    throw new TypeError(`since must be an epoch-millisecond number, got ${typeof since} ${String(since)}`);
  }
  const levels = {};
  const times = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (since !== undefined) {
      const at = event.time ? Date.parse(event.time) : NaN;
      if (!(at >= since)) continue;   // NaN-safe: untimed/unparseable excluded
    }
    levels[event.level] = (levels[event.level] ?? 0) + 1;
    if (event.time) times.push(event.time);
  }
  times.sort();
  return { levels, first: times[0] ?? null, last: times[times.length - 1] ?? null };
}
```

Note `!(at >= since)` handles NaN → excluded. Good.

