const repo = "/Users/yinlootan/src/pwk-probe-run/project";
const adr = `# Reject zone-less date-times in user-supplied dates

Status: accepted

## Context

\`--since\` accepts a date or an ISO 8601 instant. \`Date.parse\` also accepts a date-time with no zone
designator (\`2026-01-04T00:00:00\`) and reads it as *local* time, so the same input would mean a
different instant on every machine. It additionally accepts loose shapes (\`2026\`, \`2026-01\`,
\`01/01/2026\`) that nobody intends as a query bound.

## Decision

A user-supplied date must be a full instant carrying an explicit zone (\`Z\` or \`±hh:mm\`) or a date
(\`YYYY-MM-DD\`, read as UTC midnight). A zone-less date-time is rejected alongside the loose shapes,
with a message naming the offending value.

## Consequences

- \`--since\` means the same instant on every machine that runs it.
- A string \`Date.parse\` would accept can be turned away; the strict shape check exists for exactly
  that reason, so it must not be "simplified" into a bare \`Date.parse\` call.
- Rejected alternatives: loose \`Date.parse\` validation (machine-dependent meaning); defaulting a
  zone-less value to a fixed zone (still wrong for anyone outside it).
`;
await tools.write({ path: repo + "/docs/adr/0001-reject-zone-less-date-times.md", content: adr });
const a = await tools.bash({ command: `cd ${repo} && git add docs/adr/ && git commit -q -m "docs: add ADR for rejecting zone-less date-times" && git rev-parse --short HEAD && ls docs/` });
